test('Two distinct native concurrent administrative operations serialize on one revision',function()use($p,$db,&$d,$argv,&$r){$v=ver($d);$children=[];foreach(['SUSPENDED','ARCHIVED']as$status){$pipes=[];$proc=proc_open([PHP_BINARY,__FILE__,$argv[1],$argv[2],$argv[3],'worker',$d['merchant'],$v,k(),$status],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);ok(is_resource($proc));fclose($pipes[0]);$children[]=[$proc,$pipes];}$pass=0;$stale=0;foreach($children as[$proc,$pipes]){$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$exit=proc_close($proc);$r['workers'][]=['exit'=>$exit,'response'=>$out,'stderr'=>$err];if($exit===0)$pass++;elseif($exit===9&&str_contains($out,'changed'))$stale++;else throw new RuntimeException('Unexpected concurrent result');}ok($pass===1&&$stale===1);act($d,'merchant-status',['status'=>'ACTIVE_DEMO']);});
